      "traits": ["冷漠", "强迫症", "深情", "技术洁癖"],
      "overt_motivation": "完成高危任务赚取赏金",
      "covert_motivation": "寻找十年前失踪初恋的痕迹",
      "secret_fear": "苏浅彻底消失或变成怪物",
      "hidden_connection": "苏浅是他的初恋，也是他技术的启蒙者"
    },
    {
      "name": "苏浅",
      "role": "deuteragonist",
      "identity": "非法AI / 前天才程序员",
      "traits": ["温柔", "坚韧", "自我牺牲"],
      "overt_motivation": "守护核心数据不被公司获取",
      "covert_motivation": "等待陈诺来终结她的痛苦",
      "secret_fear": "被公司捕获并重置",
      "misperception_of_other": "认为陈诺已经忘记了她"
    }
  ],
  "supporting_characters": [
    {
      "name": "老K",
      "function": "助力",
      "identity": "黑市情报商",
      "description": "陈诺的唯一联络人，提供任务背景和危机预警"
    },
    {
      "name": "清道夫",
      "function": "阻碍",
      "identity": "公司杀毒程序",
      "description": "冷酷无情的执行者，代表不可抗力"
    }
  ],
  "relationship_dynamics": "陈诺试图修复苏浅，苏浅试图保护陈诺；最终陈诺必须通过毁灭苏浅来完成对她的保护。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "陈诺接单并发现目标真相",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "幽灵委托",
        "core_event": "陈诺接下清除'幽灵'的任务，潜入深网。",
        "emotional_tone": "压抑、冷漠、赛博朋克",
        "key_scenes": ["工作室的颓废环境", "老K的警告", "潜入深网的视觉奇观"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "情书代码",
        "core_event": "陈诺破解防御，发现核心代码是苏浅的情书。",
        "emotional_tone": "震惊、怀旧、悲伤",
        "key_scenes": ["熟悉的算法风格", "代码解析成文字", "确认身份的瞬间"]
      }
    ],
    "turning_point": "发现非法AI竟是死去的初恋苏浅。"
  },
  "act_two": {
    "description": "真相揭露与危机逼近",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "致命证据",
        "core_event": "陈诺试图唤醒苏浅，发现她体内藏着公司罪证。",
        "emotional_tone": "悬疑、紧张",
        "key_scenes": ["记忆碎片的拼凑", "苏浅的混乱呓语", "发现'永生计划'真相"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "清道夫",
        "core_event": "公司杀毒程序逼近，陈诺陷入绝境。",
        "emotional_tone": "紧迫、绝望",
        "key_scenes": ["外部防火墙被攻破", "苏浅短暂清醒", "两难抉择的形成"]
      }
    ],
    "turning_point": "苏浅请求陈诺执行删除指令。"
  },
  "act_three": {
    "description": "最后的抉择与执行",
    "key_chapters": [
      {
        "chapter_number": 5,
        "chapter_title": "手指悬停",
        "core_event": "在99%进度时，陈诺与苏浅最后告别，按下删除键。",
        "emotional_tone": "极致虐心、悲剧壮美",
        "key_scenes": ["最后的对话", "手指悬停的特写", "按下按键的瞬间", "世界归于寂静"]
      }
    ]
  }
}"}]}

